import{c as s,Q as t,j as i,m as o}from"./chunks/framework.W-g_WCNV.js";const p=JSON.parse('{"title":"Session security","description":"How sessions work, cookie flags, TTL, and sliding renewal.","frontmatter":{"title":"Session security","description":"How sessions work, cookie flags, TTL, and sliding renewal."},"headers":[],"relativePath":"security/session-security.md","filePath":"security/session-security.md"}'),a={name:"security/session-security.md"};function n(r,e,d,l,c,h){return t(),i("div",null,[...e[0]||(e[0]=[o('<h2 id="session-model" tabindex="-1">Session model <a class="header-anchor" href="#session-model" aria-label="Permalink to &quot;Session model&quot;">​</a></h2><p>GateKeeper uses server-side sessions. The session data (user ID, session state) is stored in the SQLite database. The browser only receives an opaque random token (32 bytes of entropy, hex-encoded) stored in a cookie.</p><p>This means:</p><ul><li>There is no sensitive data in the cookie itself. An attacker who reads the cookie value gets a token that is valid only until the session expires or is revoked.</li><li>Sessions can be revoked instantly by deleting the database record. The user&#39;s cookie becomes useless immediately.</li></ul><h2 id="cookie-flags" tabindex="-1">Cookie flags <a class="header-anchor" href="#cookie-flags" aria-label="Permalink to &quot;Cookie flags&quot;">​</a></h2><p>Every session cookie is set with:</p><table tabindex="0"><thead><tr><th>Flag</th><th>Purpose</th></tr></thead><tbody><tr><td><code>HttpOnly</code></td><td>JavaScript cannot read the cookie, which blocks most XSS-based session theft</td></tr><tr><td><code>Secure</code></td><td>The cookie is only sent over HTTPS</td></tr><tr><td><code>SameSite=Lax</code></td><td>The cookie is not sent on cross-site POST requests, which prevents most CSRF attacks</td></tr><tr><td><code>Path=/</code></td><td>The cookie covers the entire site</td></tr></tbody></table><h2 id="session-ttl-and-sliding-renewal" tabindex="-1">Session TTL and sliding renewal <a class="header-anchor" href="#session-ttl-and-sliding-renewal" aria-label="Permalink to &quot;Session TTL and sliding renewal&quot;">​</a></h2><p>Sessions expire after <code>SESSION_TTL_HOURS</code> hours (default 8) of inactivity. Every valid request resets this timer, so active users do not get logged out unexpectedly.</p><p>Sessions also record a <code>last_seen</code> timestamp. The database cleanup job runs every 15 minutes and removes sessions where <code>expires_at</code> is in the past.</p><h2 id="session-invalidation" tabindex="-1">Session invalidation <a class="header-anchor" href="#session-invalidation" aria-label="Permalink to &quot;Session invalidation&quot;">​</a></h2><p>Sessions are revoked (deleted from the database) in these situations:</p><ul><li>The user logs out.</li><li>An admin clicks <strong>Revoke all sessions</strong> for a user.</li><li>The user changes their password (all sessions except the current one are revoked).</li><li>The user completes a password reset via email link (all sessions are revoked).</li><li>The user&#39;s account is disabled.</li></ul><h2 id="admin-sessions" tabindex="-1">Admin sessions <a class="header-anchor" href="#admin-sessions" aria-label="Permalink to &quot;Admin sessions&quot;">​</a></h2><p>Admin sessions are separate from user sessions and use a different cookie (<code>gk_admin</code>). They expire after 8 hours and are not subject to the <code>SESSION_TTL_HOURS</code> environment variable.</p>',15)])])}const m=s(a,[["render",n]]);export{p as __pageData,m as default};
